54	export class QuotaExceededError extends Error {
55	  constructor(quota, holder, requested, available) {
56	    super(`quota ${String(quota)} has no room for ${requested} requested share(s)`);
57	    this.name = 'QuotaExceededError';
58	    this.code = QuotaExceededError.code;
59	    this.quota = quota;
60	    this.holder = holder ?? null;
61	    this.requested = requested;
62	    this.available = available;
63	  }
64	}
65	QuotaExceededError.code = 'QUOTA_EXCEEDED';
