node --input-type=module -e "
import { createRegistry } from './src/index.js';
let now = 0;
const r = createRegistry({ ttlMs: 100, clock: () => now });
const a = r.acquire('r', 'a', 50);
const b = r.transfer(a.token, 'b', 50);
now = 40;
console.log('renew old (false):', r.renew(a.token));
console.log('holder:', r.holder('r'));
now = 60; // b expired
console.log('sweep:', r.sweep());
console.log('transfer expired b (fences):');
try { r.transfer(b.token, 'c', 50); } catch (e) { console.log(' ', e.name, e.code, JSON.stringify(e.resource)); }
const c = r.acquire('r', 'c', 100);
console.log('epoch after retake:', c.epoch, 'stats:', JSON.stringify(r.stats()));
// self transfer allowed, advances epoch
const d = r.transfer(c.token, 'c', 100);
console.log('self-transfer epoch:', d.epoch, 'holder:', r.holder('r'));
"
